window.BraidData.sources["BraidThread"] = {"module":"BraidThread","files":[{"path":"Sources/BraidThread/AIIDetect.swift","lines":114,"bytes":6550,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":618,"scopes":[["S","AIIStatusReport",null,"public",18,18,[18,51],30,null,-1,0],["v","up",null,"public",29,29,[29,24],29,null,0,8],["E","AIIDetect",null,"public",32,32,[32,22],114,null,-1,0,[]],["f","demoRoot",["environment"],"public static",35,35,[35,108],45,[33,34],2,0],["f","status",["aii","demoRoot"],"public static",47,47,[47,88],73,null,2,0],["f","contract",["home","serving"],"public static",76,76,[76,100],84,[75,75],2,0],["f","server",["home"],"public static",87,87,[87,83],94,[86,86],2,0],["f","demoSummary",["demoRoot"],"public static",97,97,[97,66],106,[96,96],2,0],["f","demos",["demoRoot"],"public static",109,109,[109,56],113,[108,108],2,0]],"text":"//\n//  AIIDetect.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What Braid knows about an AII on this machine: its home, whether it is provisioned (layout\n//        v1, secrets), which lanes have secrets, the Thread's ports and health (stack mode, contract,\n//        embedder phase). The machine's AII is `~/.rao` (or AII_HOME); demo AIIs live under the\n//        repo's aii/ folder.\n//\n\nimport AII\nimport BraidCore\nimport Foundation\n\npublic struct AIIStatusReport: Sendable, Equatable {\n    public var name: String\n    public var home: URL\n    public var provisioned: Bool\n    public var layoutVersion: Int?\n    public var lanes: [String]\n    public var httpPort: Int\n    public var grpcPort: Int\n    public var health: LaneHealth?\n    public var problem: String?\n\n    public var up: Bool { health?.status == \"healthy\" }\n}\n\npublic enum AIIDetect {\n    /// The root demo AIIs live under: BRAID_DEMO_HOMES, else `<repo>/aii` found by walking up from the\n    /// executable to the folder holding Package.swift, else `./aii`.\n    public static func demoRoot(environment: [String: String] = ProcessInfo.processInfo.environment) -> URL {\n        if let override = environment[\"BRAID_DEMO_HOMES\"], !override.isEmpty { return URL(fileURLWithPath: (override as NSString).expandingTildeInPath, isDirectory: true) }\n        var directory = URL(fileURLWithPath: CommandLine.arguments[0]).resolvingSymlinksInPath().deletingLastPathComponent()\n        for _ in 0..<8 {\n            if FileManager.default.fileExists(atPath: directory.appendingPathComponent(\"Package.swift\").path) {\n                return directory.appendingPathComponent(\"aii\", isDirectory: true)\n            }\n            directory.deleteLastPathComponent()\n        }\n        return URL(fileURLWithPath: FileManager.default.currentDirectoryPath, isDirectory: true).appendingPathComponent(\"aii\", isDirectory: true)\n    }\n\n    public static func status(aii name: String, demoRoot: URL) async -> AIIStatusReport {\n        let home = LaneHomes.home(for: name, demoRoot: demoRoot)\n        var report = AIIStatusReport(name: name, home: home.root, provisioned: false, layoutVersion: nil, lanes: [], httpPort: AIIPortPlan.thread.http, grpcPort: AIIPortPlan.thread.grpc, health: nil, problem: nil)\n        guard FileManager.default.fileExists(atPath: home.layoutFile.path) else {\n            report.problem = \"not provisioned (no layout.json)\"\n            return report\n        }\n        report.provisioned = true\n        if let data = FileManager.default.contents(atPath: home.layoutFile.path), let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {\n            report.layoutVersion = object[\"version\"] as? Int\n        }\n        report.lanes = AIIApp.allCases.map(\\.rawValue).filter { FileManager.default.fileExists(atPath: home.secretFile(for: .app(AIIApp(rawValue: $0)!)).path) }\n        let ports = AIIConfig.load(home: home).threadPorts\n        report.httpPort = ports.http\n        report.grpcPort = ports.grpc\n        let endpoint = LaneEndpoint(address: LaneAddress(aii: name, lane: .ambient), home: home.root, httpPort: ports.http, grpcPort: ports.grpc)\n        do {\n            report.health = try await LaneClient(endpoint: endpoint, secret: \"\").health()\n        } catch let error as URLError where error.code == .cannotConnectToHost || error.code == .cannotFindHost {\n            report.problem = \"stopped (nothing answers on \\(ports.http))\"\n        } catch let error as URLError {\n            report.problem = \"Thread not answering on \\(ports.http): \\(error.localizedDescription)\"\n        } catch {\n            report.problem = \"Thread not answering on \\(ports.http): \\(error)\"\n        }\n        return report\n    }\n\n    /// The AII contract as this build links it, as install.json records it, and as the Thread serves it.\n    public static func contract(home: AIIHome = AIIHome.resolved(), serving: Int?) throws -> String {\n        guard let record = AIIInstallRecord.load(home: home) else { throw BraidFailure.missing(\"no install.json under \\(home.root.path)/aii\") }\n        let linked = AIIContract.version\n        guard record.contract == linked else {\n            throw BraidFailure.configuration(\"the installed AIIServer speaks contract \\(record.contract); this build links \\(linked)\", hint: \"update the AII package or reinstall the app\")\n        }\n        if let serving, serving != linked { throw BraidFailure.configuration(\"the Thread serves contract \\(serving); this build links \\(linked)\") }\n        return \"linked \\(linked) · installed \\(record.contract) (\\(record.appVersion), by \\(record.installedBy.rawValue)) · serving \\(serving.map(String.init) ?? \"?\")\"\n    }\n\n    /// The installed AIIServer is the binary install.json names, by SHA-256.\n    public static func server(home: AIIHome = AIIHome.resolved()) throws -> String {\n        guard let record = AIIInstallRecord.load(home: home) else { throw BraidFailure.missing(\"no install.json under \\(home.root.path)/aii\") }\n        let binary = home.serverBinary\n        guard FileManager.default.isExecutableFile(atPath: binary.path) else { throw BraidFailure.missing(\"no AIIServer at \\(binary.path)\") }\n        let found = try ContentHash.sha256Hex(fileAt: binary)\n        guard found == record.sha256 else { throw BraidFailure.data(\"AIIServer \\(found.prefix(12)) is not the one install.json names (\\(record.sha256.prefix(12)))\") }\n        return \"\\(binary.path) is install.json's (\\(found.prefix(12)))\"\n    }\n\n    /// One phrase per demo AII: its ports and whether its Thread answers. A stopped demo is not a fault.\n    public static func demoSummary(demoRoot: URL) async -> String {\n        let names = demos(demoRoot: demoRoot)\n        guard !names.isEmpty else { return \"none under \\(demoRoot.path) (braid aii create demo-a)\" }\n        var parts: [String] = []\n        for name in names {\n            let report = await status(aii: name, demoRoot: demoRoot)\n            parts.append(\"\\(name) \\(report.httpPort)/\\(report.grpcPort) \\(report.up ? \"up\" : \"stopped\")\")\n        }\n        return parts.joined(separator: \" · \")\n    }\n\n    /// The demo AIIs under the root (folders holding braid-demo.json).\n    public static func demos(demoRoot: URL) -> [String] {\n        ((try? FileManager.default.contentsOfDirectory(at: demoRoot, includingPropertiesForKeys: nil)) ?? [])\n            .filter { FileManager.default.fileExists(atPath: $0.appendingPathComponent(DemoAII.recordFile).path) }\n            .map(\\.lastPathComponent).sorted()\n    }\n}\n"},{"path":"Sources/BraidThread/DemoAII.swift","lines":165,"bytes":9574,"header":{"lines":[1,15],"what":[8,12],"pin":[13,14],"in":null,"out":null},"marks":[],"first":627,"scopes":[["S","DemoRecord",null,"public",21,21,[21,55],28,null,-1,0],["E","DemoAII",null,"public",30,30,[30,20],149,null,-1,0,[]],["f","defaultServer",[],"public static",35,35,[35,46],35,null,1,8],["f","supportsHardLinks",["_"],"public static",38,38,[38,67],44,[37,37],1,0],["f","isListening",["port"],"public static",46,46,[46,54],58,null,1,0],["f","freePorts",[],"public static",60,60,[60,68],63,null,1,0],["f","record",["name","demoRoot"],"public static",65,65,[65,80],69,null,1,0],["f","create",["name","demoRoot","at","ports","server","progress"],"public static",72,72,[73,90],108,[71,71],1,0],["f","spec",["for"],"static",110,110,[110,59],115,null,1,0],["f","start",["record","timeout","progress"],"public static",118,118,[118,124],137,[117,117],1,0],["f","stop",["record"],"public static",139,139,[139,55],148,null,1,0],["E","Blocking",null,"",152,152,[152,14],165,[151,151],-1,0,[]],["f","run",["_"],"static",153,153,[153,95],162,null,11,0],["C","ResultBox",null,"final",164,164,[164,50],164,null,11,8]],"text":"//\n//  DemoAII.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A second (or third) AII on one machine, for testing Threads that attach and detach: a home\n//        provisioned the way AII provisions one (layout.json, the four secrets), the embedder's\n//        snapshot shared with the machine's models folder by symlink so nothing re-downloads, free\n//        ports chosen from a plan, and `AIIServer thread` launched through AII's own LaunchSpecs and\n//        ManagedServer (no Developer-ID check: the installed binary is a dev build).\n//  PIN:  AII provisioning publishes secrets with link(), which exFAT cannot do, so a demo home must\n//        sit on APFS — the repo's aii/ folder by default; a target that cannot hard-link is refused.\n//\n\nimport AII\nimport BraidCore\nimport Foundation\n\npublic struct DemoRecord: Codable, Sendable, Equatable {\n    public var name: String\n    public var root: String\n    public var httpPort: Int\n    public var grpcPort: Int\n    public var server: String\n    public var createdAt: Date\n}\n\npublic enum DemoAII {\n    public static let recordFile = \"braid-demo.json\"\n    /// Port pairs tried in order, skipping any in use.\n    public static let portPlan: [(http: Int, grpc: Int)] = [(47181, 47190), (47281, 47290), (47381, 47390), (47481, 47490), (47581, 47590)]\n\n    public static func defaultServer() -> URL { AIIHome.resolved().serverBinary }\n\n    /// Whether `directory` (which must exist) supports hard links.\n    public static func supportsHardLinks(_ directory: URL) -> Bool {\n        let a = directory.appendingPathComponent(\".braid-link-\\(UUID().uuidString)\")\n        let b = directory.appendingPathComponent(\".braid-link-\\(UUID().uuidString)\")\n        defer { unlink(a.path); unlink(b.path) }\n        guard FileManager.default.createFile(atPath: a.path, contents: Data()) else { return false }\n        return link(a.path, b.path) == 0\n    }\n\n    public static func isListening(port: Int) -> Bool {\n        let socket = Darwin.socket(AF_INET, SOCK_STREAM, 0)\n        guard socket >= 0 else { return false }\n        defer { close(socket) }\n        var address = sockaddr_in()\n        address.sin_family = sa_family_t(AF_INET)\n        address.sin_port = in_port_t(port).bigEndian\n        address.sin_addr.s_addr = inet_addr(\"127.0.0.1\")\n        let result = withUnsafePointer(to: &address) { pointer in\n            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) { connect(socket, $0, socklen_t(MemoryLayout<sockaddr_in>.size)) }\n        }\n        return result == 0\n    }\n\n    public static func freePorts() throws -> (http: Int, grpc: Int) {\n        for pair in portPlan where !isListening(port: pair.http) && !isListening(port: pair.grpc) { return pair }\n        throw BraidFailure.unavailable(\"every port pair in the demo plan is in use\")\n    }\n\n    public static func record(name: String, demoRoot: URL) throws -> DemoRecord {\n        let url = demoRoot.appendingPathComponent(name, isDirectory: true).appendingPathComponent(recordFile)\n        guard FileManager.default.fileExists(atPath: url.path) else { throw BraidFailure.missing(\"no demo AII named \\(name) under \\(demoRoot.path)\", hint: \"braid aii create \\(name)\") }\n        return try JSONCoding.read(DemoRecord.self, from: url)\n    }\n\n    /// Provisions the home, shares the models folder, writes the ports, and starts the Thread.\n    public static func create(name: String, demoRoot: URL, at target: URL? = nil, ports: (http: Int, grpc: Int)? = nil, server: URL? = nil,\n                              progress: (String) -> Void = { _ in }) throws -> DemoRecord {\n        guard DocumentID.isValidHandle(name) else { throw BraidFailure.usage(\"demo names are lowercase handles: \\(name)\") }\n        let root = target ?? demoRoot.appendingPathComponent(name, isDirectory: true)\n        if FileManager.default.fileExists(atPath: root.appendingPathComponent(recordFile).path) { throw BraidFailure.exists(\"demo AII \\(name) exists at \\(root.path)\") }\n        let parent = root.deletingLastPathComponent()\n        try FileManager.default.createDirectory(at: parent, withIntermediateDirectories: true)\n        guard supportsHardLinks(parent) else {\n            throw BraidFailure.configuration(\"\\(parent.path) cannot hard-link; AII homes need APFS\", hint: \"the T9 is exFAT — leave demo homes under the repo's aii/ folder\")\n        }\n        let serverURL = server ?? defaultServer()\n        guard FileManager.default.isExecutableFile(atPath: serverURL.path) else {\n            throw BraidFailure.missing(\"no AIIServer at \\(serverURL.path)\", hint: \"install an AII app, or pass --server / BRAID_AII_SERVER\")\n        }\n        progress(\"provisioning \\(root.path)\")\n        let home = AIIHome(root: root)\n        _ = try home.provision(by: .ambient)\n        // The embedder's snapshot: the machine's models folder, shared.\n        let machineModels = AIIHome.resolved().root.appendingPathComponent(\"models\", isDirectory: true).appendingPathComponent(\"huggingface\", isDirectory: true)\n        let models = root.appendingPathComponent(\"models\", isDirectory: true)\n        try FileManager.default.createDirectory(at: models, withIntermediateDirectories: true)\n        let link = models.appendingPathComponent(\"huggingface\")\n        if FileManager.default.fileExists(atPath: machineModels.path), !FileManager.default.fileExists(atPath: link.path) {\n            try FileManager.default.createSymbolicLink(at: link, withDestinationURL: machineModels)\n            progress(\"sharing the embedder snapshots from \\(machineModels.path)\")\n        }\n        let chosen = try ports ?? freePorts()\n        var config = AIIConfig()\n        config.thread = AIIConfig.Server(httpPort: chosen.http, grpcPort: chosen.grpc, dataDir: nil, graphBackend: \"keyword\")\n        try config.write(home: home)\n        let record = DemoRecord(name: name, root: root.path, httpPort: chosen.http, grpcPort: chosen.grpc, server: serverURL.path,\n                                createdAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)))\n        try JSONCoding.write(record, to: root.appendingPathComponent(recordFile))\n        progress(\"starting AIIServer thread on \\(chosen.http)/\\(chosen.grpc)\")\n        try start(record: record, progress: progress)\n        return record\n    }\n\n    static func spec(for record: DemoRecord) -> LaunchSpec {\n        let home = AIIHome(root: URL(fileURLWithPath: record.root, isDirectory: true))\n        let options = ThreadLaunchOptions(useMLX: true, graphBackend: \"keyword\", mlxModel: AIIModels.embedding.id, ports: AIIPorts(http: record.httpPort, grpc: record.grpcPort),\n                                          mothership: false, extraArguments: [\"--no-graph-extraction\"])\n        return LaunchSpecs.thread(home: home, executable: URL(fileURLWithPath: record.server), options: options, challengeApp: .ambient, inherited: ProcessInfo.processInfo.environment)\n    }\n\n    /// Starts (or adopts) the demo's Thread and waits for its embedder.\n    public static func start(record: DemoRecord, timeout: TimeInterval = 180, progress: (String) -> Void = { _ in }) throws {\n        let home = AIIHome(root: URL(fileURLWithPath: record.root, isDirectory: true))\n        guard let secret = try home.readSecret(for: .ambient) else { throw BraidFailure.data(\"the demo home has no ambient secret\") }\n        let spec = spec(for: record)\n        let handle = try Blocking.run {\n            let server = ManagedServer(spec: spec, secret: secret, launcherApp: .ambient, policy: nil)\n            return try await server.ensureRunning(timeout: 120)\n        }\n        progress(\"Thread pid \\(handle.pid) \\(handle.adopted ? \"adopted\" : \"started\"), contract \\(handle.contract)\")\n        let endpoint = LaneEndpoint(address: LaneAddress(aii: record.name, lane: .ambient), home: home.root, httpPort: record.httpPort, grpcPort: record.grpcPort)\n        let deadline = Date().addingTimeInterval(timeout)\n        while Date() < deadline {\n            if let health = try? Blocking.run({ try await LaneClient(endpoint: endpoint, secret: \"\").health() }), health.embedderPhase == \"ready\" || health.embedderPhase == nil {\n                progress(\"embedder \\(health.embedderPhase ?? \"?\")\")\n                return\n            }\n            Thread.sleep(forTimeInterval: 2)\n        }\n        progress(\"embedder still loading after \\(Int(timeout)) s; Index calls will wait\")\n    }\n\n    public static func stop(record: DemoRecord) throws {\n        let home = AIIHome(root: URL(fileURLWithPath: record.root, isDirectory: true))\n        guard let secret = try home.readSecret(for: .ambient) else { throw BraidFailure.data(\"the demo home has no ambient secret\") }\n        let spec = spec(for: record)\n        try Blocking.run {\n            let server = ManagedServer(spec: spec, secret: secret, launcherApp: .ambient, policy: nil)\n            _ = try? await server.ensureRunning(timeout: 5)\n            await server.stop()\n        }\n    }\n}\n\n/// Runs an async operation to completion from synchronous code.\nenum Blocking {\n    static func run<T: Sendable>(_ body: @escaping @Sendable () async throws -> T) throws -> T {\n        let semaphore = DispatchSemaphore(value: 0)\n        let box = ResultBox<T>()\n        Task.detached {\n            do { box.result = .success(try await body()) } catch { box.result = .failure(error) }\n            semaphore.signal()\n        }\n        semaphore.wait()\n        return try box.result!.get()\n    }\n\n    final class ResultBox<T>: @unchecked Sendable { var result: Result<T, Error>? }\n}\n"},{"path":"Sources/BraidThread/LaneAddress.swift","lines":82,"bytes":3076,"header":{"lines":[1,15],"what":[8,12],"pin":[13,14],"in":null,"out":null},"marks":[],"first":641,"scopes":[["S","LaneAddress",null,"public",20,20,[20,80],48,null,-1,0],["i","init",["aii","lane"],"public",26,26,[26,65],29,null,0,0],["i","init",["parsing"],"public",32,32,[32,39],44,[31,31],0,0],["v","description",null,"public",46,46,[46,35],46,null,0,8],["v","isMachine",null,"public",47,47,[47,31],47,null,0,8],["E","LaneCorpus",null,"public",53,53,[53,68],82,[50,52],-1,0,["braid","app"]],["i","init",["recorded"],"public",60,60,[60,40],68,[59,59],5,0],["v","address",null,"public",70,70,[70,36],74,null,5,0],["v","description",null,"public",76,76,[76,35],81,null,5,0]],"text":"//\n//  LaneAddress.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The address of a Braid Thread inside an Ambient Intelligence Index: `<aii>/<lane>`,\n//        where `<aii>` names the machine's home (`home`) or a demo AII created by `braid aii\n//        create`, and `<lane>` is an app registered on it (ambient, craft and veil from the start,\n//        or any app that joined), whose secret puts the caller in that app's lane. A LaneCorpus\n//        says what a Thread reads there: Braid's own corpus, or the app's records.\n//  PIN:  A lane is the unit: one Braid Thread = one AII lane. The stack identity (`aii`) reads\n//        every lane but may write none, so it is never a lane address.\n//\n\nimport AII\nimport Foundation\n\npublic struct LaneAddress: Hashable, Sendable, Codable, CustomStringConvertible {\n    public static let machine = \"home\"\n\n    public var aii: String\n    public var lane: AIIApp\n\n    public init(aii: String = LaneAddress.machine, lane: AIIApp) {\n        self.aii = aii\n        self.lane = lane\n    }\n\n    /// `home/ambient`, `demo-a/craft`. A bare lane name means the machine's AII.\n    public init?(parsing text: String) {\n        let parts = text.split(separator: \"/\", omittingEmptySubsequences: false).map(String.init)\n        switch parts.count {\n        case 1:\n            guard let lane = AIIApp(rawValue: parts[0]) else { return nil }\n            self.init(lane: lane)\n        case 2:\n            guard !parts[0].isEmpty, let lane = AIIApp(rawValue: parts[1]) else { return nil }\n            self.init(aii: parts[0], lane: lane)\n        default:\n            return nil\n        }\n    }\n\n    public var description: String { \"\\(aii)/\\(lane.rawValue)\" }\n    public var isMachine: Bool { aii == Self.machine }\n}\n\n/// What a Thread reads from a lane: Braid's own corpus deposited there (owner `braid`, group\n/// `braid-<lane>`), or the records the lane's app filed (every group of the app's owner). A Thread\n/// records it as its lane: `home/veil` for Braid's corpus, `app:home/notes` for an app's records.\npublic enum LaneCorpus: Hashable, Sendable, CustomStringConvertible {\n    case braid(LaneAddress)\n    case app(LaneAddress)\n\n    public static let appPrefix = \"app:\"\n\n    /// A Thread's recorded lane: `home/veil`, or `app:home/notes`.\n    public init?(recorded text: String) {\n        if text.hasPrefix(Self.appPrefix) {\n            guard let address = LaneAddress(parsing: String(text.dropFirst(Self.appPrefix.count))) else { return nil }\n            self = .app(address)\n        } else {\n            guard let address = LaneAddress(parsing: text) else { return nil }\n            self = .braid(address)\n        }\n    }\n\n    public var address: LaneAddress {\n        switch self {\n        case .braid(let address), .app(let address): return address\n        }\n    }\n\n    public var description: String {\n        switch self {\n        case .braid(let address): return address.description\n        case .app(let address): return Self.appPrefix + address.description\n        }\n    }\n}\n"},{"path":"Sources/BraidThread/LaneClient.swift","lines":319,"bytes":16384,"header":{"lines":[1,17],"what":[8,13],"pin":[14,16],"in":null,"out":null},"marks":[[88,"Health and stats"],[110,"Deposit"],[195,"Export"]],"first":650,"scopes":[["S","LaneStats",null,"public",26,26,[26,45],30,null,-1,0],["S","LaneHealth",null,"public",32,32,[32,46],37,null,-1,0],["E","LaneError",null,"public",39,39,[39,54],53,null,-1,0,["notReachable","rejected","timeout","emptyRemove"]],["v","description",null,"public",45,45,[45,35],52,null,2,0],["A","LaneClient",null,"public",55,55,[55,24],297,null,-1,0],["f","group",["slug"],"public static",60,60,[60,53],60,null,4,8],["i","init",["endpoint","secret"],"public",63,63,[63,56],66,null,4,0],["f","withClient",["_"],"private",68,68,[68,127],78,null,4,0],["f","options",["seconds"],"private",80,80,[80,56],86,null,4,0],["f","health",["timeout"],"public nonisolated",90,90,[90,89],100,null,4,0],["f","stats",[],"public",102,102,[102,50],108,null,4,0],["f","batches",["_","size"],"public static",113,113,[113,72],116,[112,112],4,0],["f","indexRequest",["_","slug","address"],"public static",121,121,[121,147],143,[118,120],4,0],["f","deposit",["_","slug","batchSize","timeout","progress"],"public",146,146,[146,183],170,[145,145],4,0],["f","exportedIDs",["slug"],"public",172,172,[172,70],182,null,4,0],["f","waitUntilIndexed",["expected","slug","timeout","poll"],"public",184,184,[184,138],193,null,4,0],["f","recordPrefix",["_"],"public static",201,201,[201,61],201,[200,200],4,8],["f","exportRequest",["owner","groups","prefix","after","limit"],"public static",207,207,[207,157],216,[203,206],4,0],["f","exportPage",["_"],"private",218,218,[218,129],221,null,4,0],["f","exportAll",["owner","groups","prefix","pageSize"],"private",224,224,[224,146],234,[223,223],4,0],["f","exportCorpus",["slug"],"public",237,237,[237,74],244,[236,236],4,0],["f","exportRecords",["app","owner"],"public",248,248,[248,89],253,[246,247],4,0],["f","documents",["ids","owner"],"public",255,255,[255,110],264,null,4,0],["f","remove",["ids","owner"],"public",266,267,[267,92],275,null,4,0],["f","snapshotDocument",["_"],"static",277,277,[277,97],284,null,4,0],["f","recordDocument",["_"],"static",289,289,[289,95],296,[286,288],4,0],["A","LaneReader",null,"public",300,300,[300,24],319,[299,299],-1,0],["i","init",["client","owner"],"public",306,306,[306,70],309,[305,305],26,0],["f","partitionText",["documentID","partitionIndex"],"public",311,311,[311,95],318,null,26,0]],"text":"//\n//  LaneClient.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Braid's client for one lane of an AII Thread over the direct gRPC port, presenting the\n//        lane's secret: health, stats, export (paged), the deposit of documents (one tag so no\n//        extraction runs, the caller's ids and partition urls, a mandatory group), removal by id,\n//        and single-document reads for the verifier. One short-lived connection per call. Besides\n//        Braid's own corpus (owner `braid`), it exports the records the lane's app filed itself\n//        (`exportRecords`: the app's owner, all its groups, ids under `<app>/`).\n//  PIN:  Index replies before anything is persisted, so `waitUntilIndexed` polls the exported ids.\n//        ExportCorpus walks only the owner's groups in the caller's lane. An empty remove list\n//        would remove everything: refused.\n//\n\nimport AII\nimport BraidCore\nimport Foundation\nimport GRPCCore\nimport GRPCNIOTransportHTTP2\nimport Seam\n\npublic struct LaneStats: Sendable, Equatable {\n    public var documents: Int\n    public var groups: Int\n    public var owners: Int\n}\n\npublic struct LaneHealth: Sendable, Equatable {\n    public var status: String\n    public var stack: String?\n    public var contract: Int?\n    public var embedderPhase: String?\n}\n\npublic enum LaneError: Error, CustomStringConvertible {\n    case notReachable(String, String)\n    case rejected(String)\n    case timeout(missing: [String])\n    case emptyRemove\n\n    public var description: String {\n        switch self {\n        case .notReachable(let endpoint, let why): return \"\\(endpoint) is not reachable: \\(why)\"\n        case .rejected(let why): return \"the lane rejected the request: \\(why)\"\n        case .timeout(let missing): return \"the lane did not index \\(missing.count) document(s) in time: \\(missing.prefix(3).joined(separator: \", \"))\"\n        case .emptyRemove: return \"an empty remove list would remove everything; refused\"\n        }\n    }\n}\n\npublic actor LaneClient {\n    public nonisolated let endpoint: LaneEndpoint\n    private let secret: String\n    /// The owner every Braid document is filed under, and the group per corpus slug.\n    public static let owner = \"braid\"\n    public static func group(slug: String) -> String { \"braid-\\(slug)\" }\n    public static let pageSize = 100\n\n    public init(endpoint: LaneEndpoint, secret: String) {\n        self.endpoint = endpoint\n        self.secret = secret\n    }\n\n    private func withClient<R: Sendable>(_ body: (GRPCClient<HTTP2ClientTransport.Posix>) async throws -> R) async throws -> R {\n        do {\n            let transport = try HTTP2ClientTransport.Posix.http2NIOPosix(target: .ipv4(host: endpoint.host, port: endpoint.grpcPort), transportSecurity: .plaintext)\n            let interceptor = StackSecretClientInterceptor(secret: secret)\n            return try await withGRPCClient(transport: transport, interceptors: [interceptor]) { client in try await body(client) }\n        } catch let error as RPCError where error.code == .unavailable {\n            throw LaneError.notReachable(endpoint.description, error.message)\n        } catch let error as RPCError where error.code == .unauthenticated || error.code == .permissionDenied {\n            throw LaneError.rejected(error.message)\n        }\n    }\n\n    private func options(seconds: Int64) -> CallOptions {\n        var options = CallOptions.defaults\n        options.timeout = .seconds(seconds)\n        options.maxRequestMessageBytes = 16 << 20\n        options.maxResponseMessageBytes = 16 << 20\n        return options\n    }\n\n    // MARK: Health and stats\n\n    public nonisolated func health(timeout: TimeInterval = 3) async throws -> LaneHealth {\n        var request = URLRequest(url: endpoint.healthURL)\n        request.timeoutInterval = timeout\n        request.setValue(\"braid\", forHTTPHeaderField: \"X-AII-App\")\n        let (data, response) = try await URLSession.shared.data(for: request)\n        guard (response as? HTTPURLResponse)?.statusCode == 200, let object = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {\n            throw LaneError.notReachable(endpoint.description, \"health returned \\((response as? HTTPURLResponse)?.statusCode ?? -1)\")\n        }\n        return LaneHealth(status: object[\"status\"] as? String ?? \"?\", stack: object[\"stack\"] as? String, contract: object[\"contract\"] as? Int,\n                          embedderPhase: (object[\"embedder\"] as? [String: Any])?[\"phase\"] as? String)\n    }\n\n    public func stats() async throws -> LaneStats {\n        let options = options(seconds: 10)\n        let response = try await withClient { client in\n            try await Thread_V1_ThreadUpdate.Client(wrapping: client).stats(Thread_V1_ThreadStatsRequest(), options: options)\n        }\n        return LaneStats(documents: Int(response.documentCount), groups: Int(response.groupCount), owners: Int(response.ownerCount))\n    }\n\n    // MARK: Deposit\n\n    /// The batches a deposit of `count` documents is sent in.\n    public static func batches(_ count: Int, size: Int) -> [Range<Int>] {\n        let size = max(1, size)\n        return stride(from: 0, to: count, by: size).map { $0 ..< min($0 + size, count) }\n    }\n\n    /// One Index request: every document filed under the `braid` owner and the slug's group (a group\n    /// is mandatory: ExportCorpus exports only groups the owner holds), one tag (so the Thread skips\n    /// graph extraction), partitions in order with their URLs.\n    public static func indexRequest(_ documents: ArraySlice<SnapshotDocument>, slug: String, address: LaneAddress) -> Thread_V1_ThreadIndexRequest {\n        var request = Thread_V1_ThreadIndexRequest()\n        request.ownerID = owner\n        request.groupID = group(slug: slug)\n        request.groupLabel = \"Braid · \\(slug)\"\n        request.scope = \"\"\n        request.items = documents.map { document in\n            var item = Thread_V1_ThreadIndexItem()\n            item.documentID = document.id\n            item.name = document.name\n            let ordered = document.partitions.sorted { $0.index < $1.index }\n            item.texts = ordered.map(\\.text)\n            item.tags = [\"braid:\\(slug)\"]\n            item.mediaType = \"text\"\n            item.partitions = ordered.map { partition in\n                var input = Thread_V1_ThreadPartitionInput()\n                input.url = partition.url ?? DocumentID.partitionURL(aii: address.aii, lane: address.lane.rawValue, documentID: document.id, index: partition.index)\n                return input\n            }\n            return item\n        }\n        return request\n    }\n\n    /// Deposits documents under the lane's `braid` owner and the slug's group, in batches; waits until every id is exported.\n    public func deposit(_ documents: [SnapshotDocument], slug: String, batchSize: Int = 16, timeout: TimeInterval = 600, progress: (@Sendable (Int, Int) -> Void)? = nil) async throws {\n        var done = 0\n        let options = options(seconds: 600)\n        for range in Self.batches(documents.count, size: batchSize) {\n            let request = Self.indexRequest(documents[range], slug: slug, address: endpoint.address)\n            var attempt = 0\n            while true {\n                do {\n                    let response = try await withClient { client in try await Thread_V1_ThreadQuery.Client(wrapping: client).index(request, options: options) }\n                    guard response.success else { throw LaneError.rejected(\"success=false for a batch of \\(request.items.count)\") }\n                    break\n                } catch let error as RPCError where error.code == .unavailable && attempt < 60 {\n                    // The embedder is still loading: wait and retry.\n                    attempt += 1\n                    _ = error\n                    try await Task.sleep(nanoseconds: 2_000_000_000)\n                } catch let error as RPCError where error.code == .invalidArgument || error.code == .failedPrecondition {\n                    throw LaneError.rejected(error.message)\n                }\n            }\n            done += range.count\n            progress?(done, documents.count)\n        }\n        try await waitUntilIndexed(expected: Set(documents.map(\\.id)), slug: slug, timeout: timeout)\n    }\n\n    public func exportedIDs(slug: String) async throws -> Set<String> {\n        var ids = Set<String>()\n        var after = \"\"\n        while true {\n            let page = try await exportPage(Self.exportRequest(owner: Self.owner, groups: [Self.group(slug: slug)], after: after, limit: 500))\n            for document in page.documents { ids.insert(document.id) }\n            guard page.hasMore_p, let last = page.documents.last else { break }\n            after = last.id\n        }\n        return ids\n    }\n\n    public func waitUntilIndexed(expected: Set<String>, slug: String, timeout: TimeInterval = 300, poll: TimeInterval = 0.5) async throws {\n        let deadline = Date().addingTimeInterval(timeout)\n        var missing = expected\n        while Date() < deadline {\n            missing = expected.subtracting(try await exportedIDs(slug: slug))\n            if missing.isEmpty { return }\n            try await Task.sleep(nanoseconds: UInt64(poll * 1_000_000_000))\n        }\n        throw LaneError.timeout(missing: missing.sorted())\n    }\n\n    // MARK: Export\n\n    /// Records are exported in small pages: each carries its aii-record/1 envelope, up to 1 MB.\n    public static let recordsPageSize = 25\n\n    /// The id prefix of every record an app files: `<app>/<kind>/<id>`.\n    public static func recordPrefix(_ app: AIIApp) -> String { \"\\(app.rawValue)/\" }\n\n    /// One page of ExportCorpus: the owner's documents in the caller's lane, in the groups named\n    /// (none: every group the owner holds there), whose ids start with `prefix`, after `after`.\n    /// The Thread describes each partition (its id and URL) only alongside embeddings; Braid never\n    /// supplies vectors at index time, so the descriptions come back without any.\n    public static func exportRequest(owner: String, groups: [String], prefix: String = \"\", after: String, limit: Int) -> Thread_V1_ThreadExportCorpusRequest {\n        var request = Thread_V1_ThreadExportCorpusRequest()\n        request.ownerID = owner\n        request.groupIds = groups\n        request.documentIDPrefix = prefix\n        request.afterID = after\n        request.limit = Int32(limit)\n        request.includeEmbeddings = true\n        return request\n    }\n\n    private func exportPage(_ request: Thread_V1_ThreadExportCorpusRequest) async throws -> Thread_V1_ThreadExportCorpusResponse {\n        let options = options(seconds: 120)\n        return try await withClient { client in try await Thread_V1_ThreadLibrary.Client(wrapping: client).exportCorpus(request, options: options) }\n    }\n\n    /// Every page of an export, documents in id order.\n    private func exportAll(owner: String, groups: [String], prefix: String = \"\", pageSize: Int) async throws -> [Thread_V1_ThreadDocumentContent] {\n        var documents: [Thread_V1_ThreadDocumentContent] = []\n        var after = \"\"\n        while true {\n            let page = try await exportPage(Self.exportRequest(owner: owner, groups: groups, prefix: prefix, after: after, limit: pageSize))\n            documents.append(contentsOf: page.documents)\n            guard page.hasMore_p, let last = page.documents.last else { break }\n            after = last.id\n        }\n        return documents\n    }\n\n    /// The whole corpus of the slug's group, exactly as the lane stores it.\n    public func exportCorpus(slug: String) async throws -> CorpusSnapshot {\n        let documents = try await exportAll(owner: Self.owner, groups: [Self.group(slug: slug)], pageSize: Self.pageSize).map(Self.snapshotDocument)\n        let prefix = documents.first.map { id -> String in\n            let parts = id.id.split(separator: \"-\")\n            return parts.count >= 3 ? parts.dropLast().joined(separator: \"-\") + \"-\" : \"\"\n        } ?? \"\"\n        return CorpusSnapshot(documents: documents, slug: slug, source: \"aii:\\(endpoint.address)\", threadID: nil, owner: Self.owner, group: Self.group(slug: slug), documentIDPrefix: prefix)\n    }\n\n    /// Every record the lane's app filed under `owner`, in all of the owner's groups in this lane,\n    /// as a snapshot (source `app:<aii>/<app>`, group empty for every group).\n    public func exportRecords(app: AIIApp, owner: String) async throws -> CorpusSnapshot {\n        let prefix = Self.recordPrefix(app)\n        let documents = try await exportAll(owner: owner, groups: [], prefix: prefix, pageSize: Self.recordsPageSize).map(Self.recordDocument)\n        return CorpusSnapshot(documents: documents, slug: app.rawValue, source: \"\\(LaneCorpus.app(endpoint.address))\", threadID: nil, owner: owner, group: \"\",\n                              documentIDPrefix: prefix)\n    }\n\n    public func documents(ids: [String], owner: String = LaneClient.owner) async throws -> [SnapshotDocument] {\n        guard !ids.isEmpty else { return [] }\n        var request = Thread_V1_ThreadDocumentsRequest()\n        request.ownerID = owner\n        request.documentIds = ids\n        request.includeEmbeddings = true\n        let options = options(seconds: 60)\n        let response = try await withClient { client in try await Thread_V1_ThreadLibrary.Client(wrapping: client).documents(request, options: options) }\n        return response.documents.map(owner == Self.owner ? Self.snapshotDocument : Self.recordDocument)\n    }\n\n    @discardableResult\n    public func remove(ids: [String], owner: String = LaneClient.owner) async throws -> Int {\n        guard !ids.isEmpty else { throw LaneError.emptyRemove }\n        var request = Thread_V1_ThreadRemoveRequest()\n        request.ownerID = owner\n        request.documentIds = ids\n        let options = options(seconds: 60)\n        let response = try await withClient { client in try await Thread_V1_ThreadQuery.Client(wrapping: client).remove(request, options: options) }\n        return Int(response.removedCount)\n    }\n\n    static func snapshotDocument(_ content: Thread_V1_ThreadDocumentContent) -> SnapshotDocument {\n        let described = content.partitions.count == content.texts.count\n        let partitions = content.texts.enumerated().map { index, text in\n            SnapshotPartition(index: index, text: text, url: described ? content.partitions[index].url : nil, threadPartitionID: described ? content.partitions[index].id : nil)\n        }\n        return SnapshotDocument(id: content.id, name: content.name, ownerID: content.ownerID, groupID: content.groupID, groupLabel: content.groupLabel,\n                                createdAt: content.createdAt, mediaType: content.mediaType, partitions: partitions)\n    }\n\n    /// An app's record as a snapshot document: as `snapshotDocument`, except that a partition with no\n    /// url of its own, which the Thread describes by its storage address (`file:…/documents/<id>`),\n    /// has none (AII's own rule for a record read back).\n    static func recordDocument(_ content: Thread_V1_ThreadDocumentContent) -> SnapshotDocument {\n        var document = snapshotDocument(content)\n        let storage = \"/documents/\\(content.id)\"\n        for i in document.partitions.indices {\n            if let url = document.partitions[i].url, url.hasPrefix(\"file:\"), url.hasSuffix(storage) { document.partitions[i].url = nil }\n        }\n        return document\n    }\n}\n\n/// Reads live partition texts from a lane for the verifier, caching documents.\npublic actor LaneReader {\n    private let client: LaneClient\n    private let owner: String\n    private var cache: [String: [String]] = [:]\n\n    /// `owner`: whose documents these are (Braid's own corpus, or the lane app's records).\n    public init(client: LaneClient, owner: String = LaneClient.owner) {\n        self.client = client\n        self.owner = owner\n    }\n\n    public func partitionText(documentID: String, partitionIndex: Int) async throws -> String? {\n        if cache[documentID] == nil {\n            let documents = try await client.documents(ids: [documentID], owner: owner)\n            cache[documentID] = documents.first?.partitions.sorted { $0.index < $1.index }.map(\\.text) ?? []\n        }\n        guard let partitions = cache[documentID], partitions.indices.contains(partitionIndex) else { return nil }\n        return partitions[partitionIndex]\n    }\n}\n"},{"path":"Sources/BraidThread/LaneHome.swift","lines":60,"bytes":2835,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":679,"scopes":[["S","LaneEndpoint",null,"public",18,18,[18,48],27,null,-1,0],["v","healthURL",null,"public",25,25,[25,30],25,null,0,8],["v","description",null,"public",26,26,[26,35],26,null,0,8],["E","LaneHomes",null,"public",29,29,[29,22],60,null,-1,0,[]],["f","home",["for","demoRoot"],"public static",31,31,[31,71],33,[30,30],3,0],["f","endpoint",["for","demoRoot"],"public static",35,35,[35,96],42,null,3,0],["f","secret",["for","demoRoot"],"public static",45,45,[45,88],51,[44,44],3,0],["f","owner",["for","demoRoot"],"public static",56,56,[56,80],59,[53,55],3,0]],"text":"//\n//  LaneHome.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Which AII a lane address names and how to reach its Thread: the machine's home (`~/.rao`,\n//        or AII_HOME) or a demo home Braid created under <repo>/aii/<name>; the Thread's ports from\n//        the home's aii/config.json (the shared-stack plan 47081/47090 by default); the lane's\n//        secret from the home's secrets/, read the way AII reads it.\n//\n\nimport AII\nimport BraidCore\nimport Foundation\n\npublic struct LaneEndpoint: Sendable, Equatable {\n    public var address: LaneAddress\n    public var home: URL\n    public var httpPort: Int\n    public var grpcPort: Int\n    public var host = \"127.0.0.1\"\n\n    public var healthURL: URL { URL(string: \"http://\\(host):\\(httpPort)/health\")! }\n    public var description: String { \"\\(address) @ \\(home.path) grpc:\\(grpcPort)\" }\n}\n\npublic enum LaneHomes {\n    /// The home an `<aii>` name refers to: `home` is the machine's, anything else a demo under `demoRoot`.\n    public static func home(for aii: String, demoRoot: URL) -> AIIHome {\n        aii == LaneAddress.machine ? AIIHome.resolved() : AIIHome(root: demoRoot.appendingPathComponent(aii, isDirectory: true))\n    }\n\n    public static func endpoint(for address: LaneAddress, demoRoot: URL) throws -> LaneEndpoint {\n        let home = home(for: address.aii, demoRoot: demoRoot)\n        guard FileManager.default.fileExists(atPath: home.layoutFile.path) else {\n            throw BraidFailure.unavailable(\"no AII home at \\(home.root.path)\", hint: address.isMachine ? \"install an app that provisions ~/.rao, or set AII_HOME\" : \"run braid aii create \\(address.aii)\")\n        }\n        let ports = AIIConfig.load(home: home).threadPorts\n        return LaneEndpoint(address: address, home: home.root, httpPort: ports.http, grpcPort: ports.grpc)\n    }\n\n    /// The lane's secret: the app's, as AII reads it (owner, mode, 64 hex).\n    public static func secret(for address: LaneAddress, demoRoot: URL) throws -> String {\n        let home = home(for: address.aii, demoRoot: demoRoot)\n        guard let secret = try home.readSecret(for: .app(address.lane)) else {\n            throw BraidFailure.unavailable(\"no secret for \\(address.lane.rawValue) in \\(home.root.path)/secrets\")\n        }\n        return secret\n    }\n\n    /// Whom the lane's app files its records under: the owner its manifest entry names (an app that\n    /// joined with `owner: .local` files under aii-local), else a new lane's default, `local-<app>`.\n    /// The owner AIIInstance files under.\n    public static func owner(for address: LaneAddress, demoRoot: URL) -> String {\n        let home = home(for: address.aii, demoRoot: demoRoot)\n        return (home.lane(address.lane)?.owner ?? AIILanes.defaultOwner(for: address.lane)).rawValue\n    }\n}\n"},{"path":"Sources/BraidThread/LaneSource.swift","lines":89,"bytes":4277,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[[61,"An app's records"]],"first":687,"scopes":[["E","LaneSource",null,"public",17,17,[17,23],89,null,-1,0,[]],["f","client",["for","demoRoot"],"public static",18,18,[18,92],22,null,0,0],["f","snapshot",["address","demoRoot"],"public static",25,25,[25,94],28,[24,24],0,0],["f","ingest",["_","into","demoRoot","batchSize","progress"],"public static",31,31,[31,192],44,[30,30],0,0],["f","wipe",["address","demoRoot"],"public static",47,47,[47,79],54,[46,46],0,0],["f","stats",["address","demoRoot"],"public static",56,56,[56,86],59,null,0,0],["f","records",["app","demoRoot"],"public static",65,65,[65,97],69,[63,64],0,0],["f","owner",["of","demoRoot"],"public static",72,72,[72,77],77,[71,71],0,0],["f","emptyRefusal",["_"],"public static",80,80,[80,74],88,[79,79],0,0]],"text":"//\n//  LaneSource.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A lane as a corpus: export what Braid deposited there (owner `braid`, group `braid-<lane>`)\n//        as a snapshot, deposit a corpus into it (ingest), remove what was deposited (wipe). The\n//        slug of a lane's group is the lane's own name, so one lane holds one Braid corpus.\n//\n\nimport AII\nimport BraidCore\nimport Foundation\n\npublic enum LaneSource {\n    public static func client(for address: LaneAddress, demoRoot: URL) throws -> LaneClient {\n        let endpoint = try LaneHomes.endpoint(for: address, demoRoot: demoRoot)\n        let secret = try LaneHomes.secret(for: address, demoRoot: demoRoot)\n        return LaneClient(endpoint: endpoint, secret: secret)\n    }\n\n    /// The lane's Braid corpus, exactly as the Thread stores it.\n    public static func snapshot(address: LaneAddress, demoRoot: URL) throws -> CorpusSnapshot {\n        let client = try client(for: address, demoRoot: demoRoot)\n        return try Blocking.run { try await client.exportCorpus(slug: address.lane.rawValue) }\n    }\n\n    /// Deposits a snapshot's documents into the lane and waits until they are exported.\n    public static func ingest(_ snapshot: CorpusSnapshot, into address: LaneAddress, demoRoot: URL, batchSize: Int = 16, progress: @escaping @Sendable (Int, Int) -> Void = { _, _ in }) throws {\n        let client = try client(for: address, demoRoot: demoRoot)\n        let slug = address.lane.rawValue\n        let documents = snapshot.documents.map { document -> SnapshotDocument in\n            var copy = document\n            copy.partitions = document.partitions.map { partition in\n                var p = partition\n                p.url = DocumentID.partitionURL(aii: address.aii, lane: slug, documentID: document.id, index: partition.index)\n                return p\n            }\n            return copy\n        }\n        try Blocking.run { try await client.deposit(documents, slug: slug, batchSize: batchSize, progress: progress) }\n    }\n\n    /// Removes every Braid document of the lane; returns how many.\n    public static func wipe(address: LaneAddress, demoRoot: URL) throws -> Int {\n        let client = try client(for: address, demoRoot: demoRoot)\n        return try Blocking.run {\n            let ids = try await client.exportedIDs(slug: address.lane.rawValue)\n            guard !ids.isEmpty else { return 0 }\n            return try await client.remove(ids: ids.sorted())\n        }\n    }\n\n    public static func stats(address: LaneAddress, demoRoot: URL) throws -> LaneStats {\n        let client = try client(for: address, demoRoot: demoRoot)\n        return try Blocking.run { try await client.stats() }\n    }\n\n    // MARK: An app's records\n\n    /// Every record the lane's app filed there itself (with AIIInstance.remember): its owner's\n    /// documents in all of the owner's groups in the lane, as the Thread stores them.\n    public static func records(app address: LaneAddress, demoRoot: URL) throws -> CorpusSnapshot {\n        let client = try client(for: address, demoRoot: demoRoot)\n        let owner = LaneHomes.owner(for: address, demoRoot: demoRoot)\n        return try Blocking.run { try await client.exportRecords(app: address.lane, owner: owner) }\n    }\n\n    /// The owner a lane corpus is read under: `braid` for Braid's own corpus, the app's for its records.\n    public static func owner(of corpus: LaneCorpus, demoRoot: URL) -> String {\n        switch corpus {\n        case .braid: return LaneClient.owner\n        case .app(let address): return LaneHomes.owner(for: address, demoRoot: demoRoot)\n        }\n    }\n\n    /// Why no Thread can be made from an empty lane corpus.\n    public static func emptyRefusal(_ corpus: LaneCorpus) -> BraidFailure {\n        switch corpus {\n        case .braid(let address):\n            return BraidFailure.missing(\"\\(address) holds no Braid documents\", hint: \"braid aii ingest \\(address) --from dataset:<name>#<node>\")\n        case .app(let address):\n            return BraidFailure.missing(\"\\(address.lane.rawValue) has filed no records in \\(address)\",\n                                        hint: \"an app files records with AIIInstance.remember once it has joined that AII\")\n        }\n    }\n}\n"},{"path":"Sources/BraidThread/LivePartitionReader.swift","lines":67,"bytes":3012,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":696,"scopes":[["C","LivePartitionReader",null,"public final",17,17,[17,78],67,null,-1,0],["i","init",["lanes","demoRoot","fallback"],"public",27,27,[27,89],31,[26,26],0,0],["f","partitionText",["documentID","partitionIndex"],"public",33,33,[33,89],37,null,0,0],["f","reader",["for"],"private",39,39,[39,69],47,null,0,0],["f","lanes",["for"],"public static",51,51,[51,81],66,[49,50],0,0]],"text":"//\n//  LivePartitionReader.swift\n//  BraidThread\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The verifier's reader for `braid verify --live`: a document held in an AII lane is re-read\n//        from that lane as it stands now (so an edit or a removal since the session shows as stale or\n//        missing), under the owner it was read with (Braid's corpus, or the lane app's records); any\n//        other document is read from the fallback (the Thread's snapshot).\n//\n\nimport BraidCore\nimport Foundation\n\npublic final class LivePartitionReader: PartitionReading, @unchecked Sendable {\n    private let lanes: [String: LaneCorpus]\n    private let demoRoot: URL\n    private let fallback: PartitionReading?\n    private var readers: [LaneCorpus: LaneReader] = [:]\n    private let lock = NSLock()\n    /// Every lane read so far.\n    public private(set) var used: Set<LaneCorpus> = []\n\n    /// `lanes` maps a document id to the lane that holds it.\n    public init(lanes: [String: LaneCorpus], demoRoot: URL, fallback: PartitionReading?) {\n        self.lanes = lanes\n        self.demoRoot = demoRoot\n        self.fallback = fallback\n    }\n\n    public func partitionText(documentID: String, partitionIndex: Int) throws -> String? {\n        guard let corpus = lanes[documentID] else { return try fallback?.partitionText(documentID: documentID, partitionIndex: partitionIndex) }\n        let reader = try reader(for: corpus)\n        return try Blocking.run { try await reader.partitionText(documentID: documentID, partitionIndex: partitionIndex) }\n    }\n\n    private func reader(for corpus: LaneCorpus) throws -> LaneReader {\n        lock.lock()\n        defer { lock.unlock() }\n        if let existing = readers[corpus] { return existing }\n        let reader = LaneReader(client: try LaneSource.client(for: corpus.address, demoRoot: demoRoot), owner: LaneSource.owner(of: corpus, demoRoot: demoRoot))\n        readers[corpus] = reader\n        used.insert(corpus)\n        return reader\n    }\n\n    /// Which lane holds each document a session's generations touched: a partition's Thread (by its\n    /// thread id) names its lane in the session header or an attach line.\n    public static func lanes(for session: LoggedSession) -> [String: LaneCorpus] {\n        let threads = session.header.threads + session.membership.filter { $0.kind == \"attach\" }.map(\\.thread)\n        var laneOfThread: [String: LaneCorpus] = [:]\n        for thread in threads {\n            guard let id = thread.threadID, let lane = thread.lane, let corpus = LaneCorpus(recorded: lane) else { continue }\n            laneOfThread[id] = corpus\n        }\n        var lanes: [String: LaneCorpus] = [:]\n        for generation in session.generations {\n            for partition in generation.end?.partitions ?? [] {\n                guard let id = partition.threadID, let corpus = laneOfThread[id] else { continue }\n                lanes[partition.documentID] = corpus\n            }\n        }\n        return lanes\n    }\n}\n"}]};
